window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-82ae53f2e77f8a56"]={"versions": [{"id": "FIG-82ae53f2e77f8a56", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.\n</li><li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.\n</li><li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileStorageInterface</code></strong>:\n<ul class=\"fig-list\"><li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis n vorab deklarierte Dateielemente.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileElement</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).\n</li><li>Repräsentiert eine konkrete, im Manifest definierte Datei.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.\n</li><li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ComSpec::PersistencyRedundancyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>none</code> – Keine softwareseitige Redundanz.\n</li><li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).\n</li><li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.\n</li></ul>\n</li><li><strong><code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.\n</li><li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.\n</li></ul>\n</li><li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.\n</li><li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.\n</li><li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Software-Update &amp; Deployment (UCM-Verhalten):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.\n</li><li><strong>Evaluierungshierarchie:</strong>\n<ol class=\"fig-list\"><li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.\n</li><li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.\n</li></ol>\n</li></ul>\n</li><li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong>\n<ul class=\"fig-list\"><li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.\n</li><li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong>\n<ul class=\"fig-list\"><li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.\n</li><li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Quotas:</strong>\n<ul class=\"fig-list\"><li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).\n</li><li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.\n</li></ul>\n</li><li><strong>Integrität &amp; ASIL-Anforderungen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.\n</li></ul>\n</li><li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R22-11.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-36684de6efb79da7", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).\n</li><li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.\n</li><li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.\n</li><li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileStorageInterface</code></strong>:\n<ul class=\"fig-list\"><li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis n vorab deklarierte Dateielemente.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileElement</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).\n</li><li>Repräsentiert eine konkrete, im Manifest definierte Datei.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.\n</li><li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyRedundancyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>none</code> – Keine softwareseitige Redundanz.\n</li><li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).\n</li><li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.\n</li></ul>\n</li><li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.\n</li><li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.\n</li></ul>\n</li><li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.\n</li><li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.\n</li><li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Software-Update &amp; Deployment (UCM-Verhalten):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.\n</li><li><strong>Evaluierungshierarchie:</strong>\n<ol class=\"fig-list\"><li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.\n</li><li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.\n</li></ol>\n</li></ul>\n</li><li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong>\n<ul class=\"fig-list\"><li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.\n</li><li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong>\n<ul class=\"fig-list\"><li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.\n</li><li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).\n</li></ul>\n</li><li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong>\n<ul class=\"fig-list\"><li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Quotas:</strong>\n<ul class=\"fig-list\"><li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).\n</li><li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.\n</li></ul>\n</li><li><strong>Integrität &amp; ASIL-Anforderungen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.\n</li></ul>\n</li><li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cfd87860b265c3c0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).\n</li><li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.\n</li><li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.\n</li><li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileStorageInterface</code></strong>:\n<ul class=\"fig-list\"><li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis n vorab deklarierte Dateielemente.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileElement</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).\n</li><li>Repräsentiert eine konkrete, im Manifest definierte Datei.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.\n</li><li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyRedundancyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>none</code> – Keine softwareseitige Redundanz.\n</li><li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).\n</li><li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.\n</li></ul>\n</li><li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.\n</li><li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.\n</li></ul>\n</li><li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.\n</li><li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.\n</li><li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Software-Update &amp; Deployment (UCM-Verhalten):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.\n</li><li><strong>Evaluierungshierarchie:</strong>\n<ol class=\"fig-list\"><li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.\n</li><li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.\n</li></ol>\n</li></ul>\n</li><li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong>\n<ul class=\"fig-list\"><li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.\n</li><li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong>\n<ul class=\"fig-list\"><li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.\n</li><li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).\n</li></ul>\n</li><li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong>\n<ul class=\"fig-list\"><li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Quotas:</strong>\n<ul class=\"fig-list\"><li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).\n</li><li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.\n</li></ul>\n</li><li><strong>Integrität &amp; ASIL-Anforderungen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.\n</li></ul>\n</li><li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a50f6539c41b688", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (AUTOSAR M2-Metamodell-Ausschnitt).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (Release R22-11), Spezifikation <code>AUTOSAR_TPS_ManifestSpecification</code>.\n</li><li><strong>Funktionale Einordnung:</strong> Modellierung der Port-Schnittstellen für den Functional Cluster Persistency (<code>ara::per</code>). Das Metamodell definiert die deklarative Konfiguration für dateibasierten Speicher (<code>PersistencyFileStorageInterface</code>) zur Entkopplung der Applikationslogik von der physischen Dateisystem- und Speicherverwaltung (Flash, eMMC, NVRAM) sowie zur Festlegung von Redundanz- und Update-Strategien bei Software-Aktualisierungen via UCM (Update and Configuration Management).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyInterface</code></strong> <em>(abstrakt, Package <code>PortInterface</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse aller Persistenz-Schnittstellen (FileStorage und KeyValueStorage).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contractVersion: StrongRevisionLabelString [0..1]</code> – Streng typisierte Versionsbezeichnung der Schnittstellenvereinbarung (Contract Versioning).\n</li><li><code>minimumSustainedSize: PositiveInteger [0..1]</code> – Garantiertes Speichervolumen in Bytes, das das System für diese Schnittstelle vorhalten muss.\n</li><li><code>redundancy: PersistencyRedundancyEnum [0..1]</code> – Redundanzkonfiguration auf Speichergesamt-Ebene.\n</li><li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code> – Verhalten bei Software-Updates auf Ebene des Gesamtspeichers.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileStorageInterface</code></strong>:\n<ul class=\"fig-list\"><li>Konkrete Spezialisierung von <code>PersistencyInterface</code> (Generalisierungsbeziehung).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>maxNumberOfFiles: PositiveInteger [0..1]</code> – Obergrenze der gleichzeitig verwaltbaren Dateien im File Storage.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Komposition <code>+fileElement: PersistencyFileElement [0..*]</code> – Aggregiert 0 bis n vorab deklarierte Dateielemente.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyInterfaceElement</code></strong> <em>(abstrakt, Package <code>Identifiable</code>)</em>:\n<ul class=\"fig-list\"><li>Basisklasse für einzelne Elemente innerhalb einer Persistenz-Schnittstelle; erbt Identifizierbarkeit (<code>shortName</code>).\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>updateStrategy: PersistencyElementLevelUpdateStrategyEnum [0..1]</code> – Granulare Update-Strategie für das einzelne Element.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PersistencyFileElement</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>PersistencyInterfaceElement</code> (Generalisierungsbeziehung).\n</li><li>Repräsentiert eine konkrete, im Manifest definierte Datei.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>contentUri: UriString [0..1]</code> – Pfad/URI zum initialen Dateiinhalt im Software-Paket.\n</li><li><code>fileName: String [0..1]</code> – Logischer Dateiname innerhalb des Dateispeichers.\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>PersistencyRedundancyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>none</code> – Keine softwareseitige Redundanz.\n</li><li><code>redundant</code> – Gesamter Speicher wird redundant/gespiegelt vorgehalten (z. B. M-out-of-N, Duplizierung).\n</li><li><code>redundantPerElement</code> – Redundanz wird granular auf Dateiebene gesteuert.\n</li></ul>\n</li><li><strong><code>PersistencyCollectionLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>keepExisting</code> – Bei Aktualisierung des Software-Clusters bleibt der bestehende Dateispeicher unverändert.\n</li><li><code>delete</code> – Der gesamte Speicherbereich wird bei einem Update geleert/gelöscht.\n</li></ul>\n</li><li><strong><code>PersistencyElementLevelUpdateStrategyEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>overwrite</code> – Bestehende Zieldatei wird mit dem Stand aus <code>contentUri</code> überschrieben.\n</li><li><code>keepExisting</code> – Existierende Zieldatei bleibt unberührt; fehlt sie, wird sie initial angelegt.\n</li><li><code>delete</code> – Datei wird im Rahmen des Updates gezielt entfernt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet die Grafik keine Laufzeitsequenzen ab; das dynamische Verhalten manifestiert sich in zwei Phasen:</p>\n<ol class=\"fig-list\"><li><strong>Software-Update &amp; Deployment (UCM-Verhalten):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Aktivierung eines neuen Software-Cluster-Pakets via <code>ara::ucm</code>.\n</li><li><strong>Evaluierungshierarchie:</strong>\n<ol class=\"fig-list\"><li>Auswertung von <code>PersistencyInterface.updateStrategy</code>: Bei <code>delete</code> wird der physische Speicherordner komplett zurückgesetzt.\n</li><li>Bei <code>keepExisting</code>: Iteration über alle <code>fileElement</code>-Instanzen. Ist für ein <code>PersistencyFileElement</code> eine <code>updateStrategy</code> definiert, überschreibt sie das Collection-Verhalten (<code>overwrite</code>, <code>keepExisting</code>, <code>delete</code>) und synchronisiert den Inhalt über <code>contentUri</code>.\n</li></ol>\n</li></ul>\n</li><li><strong>Laufzeit-Zugriff (<code>ara::per</code>-Stack):</strong>\n<ul class=\"fig-list\"><li>Applikation öffnet den Storage über <code>ara::per::OpenFileStorage(...)</code> via Port-Referenz.\n</li><li>Der Persistency-Stack prüft Quotas (<code>maxNumberOfFiles</code>, <code>minimumSustainedSize</code>) gegen das Dateisystem und erzwingt bei I/O-Operationen transparent die konfigurierte Redundanz (<code>PersistencyRedundancyEnum</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurations- und Manifestbindung (TPS_MANI_01142, RS_MANI_00027):</strong>\n<ul class=\"fig-list\"><li><code>PersistencyFileStorageInterface</code> dient als Typ für <code>PRPortPrototype</code>, <code>PPortPrototype</code> oder <code>RPortPrototype</code> im Application Design Manifest.\n</li><li>Das Deployment-Mapping verknüpft dieses Interface mit physischen Speicherpfaden im Ausführungsmanifest (<code>PersistencyFileStorageDeployment</code>).\n</li></ul>\n</li><li><strong>Schnittstellen-Versionierung (<code>contractVersion</code>):</strong>\n<ul class=\"fig-list\"><li>Mit <code>contractVersion: StrongRevisionLabelString [0..1]</code> wird die formale Versionierung der Persistenz-Schnittstelle gemäß AUTOSAR-Revisionsetikett eingeführt. Integratoren und UCM können damit zur Entwurfs- und Update-Zeit prüfen, ob die Softwareversion einer Applikation mit dem Datenmodell und Speicherinhalt der Schnittstelle kompatibel ist.\n</li></ul>\n</li><li><strong>Ressourcenallokation &amp; Quotas:</strong>\n<ul class=\"fig-list\"><li><code>minimumSustainedSize</code> und <code>maxNumberOfFiles</code> sind bindende Vorgaben für Integratoren. Sie bestimmen Partitionsgrößen, POSIX-Quotas und Inode-Reservierungen im Zielbetriebssystem (z. B. QNX, Linux).\n</li><li>Überschreitet eine Applikation zur Laufzeit <code>maxNumberOfFiles</code>, muss der Stack Operationen wie <code>OpenFileWrite()</code> mit dem Fehler <code>ara::per::PerErrc::kOutOfStorage</code> bzw. <code>kQuotaExceeded</code> ablehnen.\n</li></ul>\n</li><li><strong>Integrität &amp; ASIL-Anforderungen:</strong>\n<ul class=\"fig-list\"><li>Ist <code>redundancy</code> auf <code>redundant</code> konfiguriert, implementiert der <code>ara::per</code>-Stack automatische Prüfsummen (CRC32/CRC64), Shadow-Files oder Block-Level-Replikation zur Erkennung und Behebung von Bitkippern/Flash-Degradation, ohne dass die Applikation eigene Redundanzlogik implementieren muss.\n</li></ul>\n</li><li><strong>Release-Gültigkeit:</strong> Vollständig konform zu AUTOSAR Adaptive Platform R23-11.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-82ae53f2e77f8a56", "to": "FIG-36684de6efb79da7", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PersistencyInterface</code>: Neues Attribut <code>+ contractVersion: StrongRevisionLabelString [0..1]</code> ergänzt.\n</li><li><code>PersistencyRedundancyEnum</code>: Paket-Präfix <code>ComSpec::</code> im Namen der Enumeration entfernt.\n</li><li><code>PersistencyCollectionLevelUpdateStrategyEnum</code>: Paket-Präfix <code>PortInterface::</code> im Namen der Enumeration entfernt.\n</li></ul>"}, {"from": "FIG-36684de6efb79da7", "to": "FIG-cfd87860b265c3c0", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PersistencyRedundancyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.\n</li><li><code>PersistencyCollectionLevelUpdateStrategyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.\n</li><li><code>PersistencyElementLevelUpdateStrategyEnum</code>: UML-Kompartiment-Kennzeichnung <em>literals</em> oberhalb der Aufzählungswerte ergänzt.\n</li></ul>"}, {"from": "FIG-cfd87860b265c3c0", "to": "FIG-2a50f6539c41b688", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
